import { createServer } from 'vite'
import { createHttpTestContext, setActiveDatabase } from '../../../test/helpers.js'
import { makeActivity, makeGoal, makeMember, makeProject, makeStory, makeTask, makeUser } from '../../../test/factories.js'
import { registerUmlRoutes } from '../../../src/modules/uml/plugin.js'

if (!process.send) throw new Error('This test server requires the verifier IPC channel')
const ctx = await createHttpTestContext()
setActiveDatabase(ctx.db)
const pm = await makeUser('uml-browser-pm@example.invalid')
const viewer = await makeUser('uml-browser-viewer@example.invalid')
const { projectId } = await makeProject(pm.id, 'UML 合成验收项目')
await makeMember(projectId, viewer.id, 'VIEWER')
const goalId = await makeGoal(projectId, '合成目标')
const activityId = await makeActivity(goalId, '合成活动')
const storyId = await makeStory(activityId, { title: '合成故事' })
const taskId = await makeTask(storyId, viewer.id, pm.id, { title: '合成任务' })
if (!ctx.app.hasRoute({ method: 'POST', url: '/projects/:projectId/uml-diagrams' })) registerUmlRoutes(ctx.app, { prisma: ctx.db })
const address = await ctx.app.listen({ host: '127.0.0.1', port: 0 })
const vite = await createServer({ configFile: 'web/vite.config.ts', server: {
  host: '127.0.0.1', port: 0, strictPort: false,
  proxy: { '/api': { target: address, changeOrigin: true, rewrite: path => path.replace(/^\/api/, '') } },
} })
await vite.listen()
const webAddress = vite.httpServer!.address()
if (!webAddress || typeof webAddress === 'string') throw new Error('No test web address')
process.send({ type: 'ready', url: `http://127.0.0.1:${webAddress.port}`, projectId, goalId, activityId, storyId, taskId,
  pmToken: ctx.loginAs(pm.id), viewerToken: ctx.loginAs(viewer.id) })
let closing = false
async function close() {
  if (closing) return
  closing = true
  await vite.close()
  await ctx.dispose()
  process.exit(0)
}
process.on('message', value => { if (value === 'close') void close() })
process.on('disconnect', () => void close())
process.on('SIGTERM', () => void close())

/** US-15 own-domain plugin. B alone owns production registration in src/routes.ts.
 * IMPORTANT: non-PM reads currently fail closed pending durable visibility guard.
 * Do not mount as an accepted feature or claim AC5 completion; see service.ts.
 */
import type { FastifyInstance } from 'fastify'
import type { ZodType, ZodTypeDef } from 'zod'
import { currentUserId, requireAuth } from '../../auth/actor.js'
import type { RouteContext } from '../../routes.js'
import { AppError } from '../../shared/errors.js'
import { toFieldErrors } from '../../shared/validation.js'
import { umlContentSchema, umlCreateSchema, umlListQuerySchema, umlPatchSchema } from './schemas.js'
import { createUmlDiagram, deleteUmlDiagram, getUmlDiagram, listUmlDiagrams, patchUmlDiagram, putUmlContent } from './service.js'

function parse<T>(schema: ZodType<T, ZodTypeDef, unknown>, value: unknown): T {
  const result = schema.safeParse(value)
  if (!result.success) throw new AppError(422, 'VALIDATION_FAILED', '字段校验失败', toFieldErrors(result.error.issues))
  return result.data
}
export function registerUmlRoutes(app: FastifyInstance, ctx: RouteContext): void {
  const options = { preHandler: requireAuth }
  app.get('/projects/:projectId/uml-diagrams', options, async req => {
    const { projectId } = req.params as { projectId: string }
    const query = parse(umlListQuerySchema, req.query)
    return listUmlDiagrams(ctx.prisma, currentUserId(req), projectId, query.kind)
  })
  app.get('/uml-diagrams/:diagramId', options, async req => {
    const { diagramId } = req.params as { diagramId: string }
    return getUmlDiagram(ctx.prisma, currentUserId(req), diagramId)
  })
  app.post('/projects/:projectId/uml-diagrams', options, async (req, reply) => {
    const { projectId } = req.params as { projectId: string }
    const input = parse(umlCreateSchema, req.body)
    return reply.status(201).send(await createUmlDiagram(ctx.prisma, currentUserId(req), projectId, input))
  })
  app.patch('/uml-diagrams/:diagramId', options, async req => {
    const { diagramId } = req.params as { diagramId: string }
    return patchUmlDiagram(ctx.prisma, currentUserId(req), diagramId, parse(umlPatchSchema, req.body))
  })
  app.put('/uml-diagrams/:diagramId/content', options, async req => {
    const { diagramId } = req.params as { diagramId: string }
    return putUmlContent(ctx.prisma, currentUserId(req), diagramId, parse(umlContentSchema, req.body))
  })
  app.delete('/uml-diagrams/:diagramId', options, async (req, reply) => {
    const { diagramId } = req.params as { diagramId: string }
    await deleteUmlDiagram(ctx.prisma, currentUserId(req), diagramId)
    return reply.status(204).send()
  })
}

/**
 * 测试数据工厂（T0.5 交付，**全员只读**）
 *
 * 契约《Sprint 1 需求规格说明书 · 接口契约》「Testing Decisions → 测试数据工厂」规定：
 *
 *   makeUser(account, displayName)                  → UserBrief
 *   makeProject(ownerUserId, name)                  → { projectId, ownerUserId }
 *   makeMember(projectId, userId, role)             → void
 *   makeGoal(projectId, name)                       → goalId
 *   makeActivity(goalId, name)                      → activityId
