    // 删除顺序：可见性记录 → 任务。数组形式 `$transaction` 在一个事务内按顺序执行，
    // 任一步失败则整体回滚，因此不会出现「任务已删但可见性记录残留」或反向的中间态。
    //
    // ★ 并发双删竞态：第二个请求的 `task.delete` 会因行已被删而抛 Prisma P2025。
    //   按契约 I-3，映射为与「任务不存在」逐字一致的 404；`$transaction` 会自动
    //   回滚第一步的 `deleteMany`，可见性记录不会被误删（事务语义由测试断言）。
    //   只捕获 P2025，其它错误仍原样抛出转 500。
    try {
      await prisma.$transaction([
        prisma.objectVisibility.deleteMany({
          where: { objectType: 'task', objectId: task.id },
        }),
        prisma.task.delete({ where: { id: task.id } }),
      ])
    } catch (error) {
      if (isRecordNotFoundError(error)) {
        throw notFound()
      }
      throw error
    }

    // 契约决策 I-3：删除成功返回 HTTP 204，无响应体。
    return reply.status(204).send()
  })
}

import { useCallback, useEffect, useRef, useState, type ChangeEvent } from 'react'
import { ApiError } from '../../api'
import {
  deleteAttachment,
  downloadAttachment,
  listTaskAttachments,
  uploadTaskAttachment,
  validateAttachmentFile,
  type AttachmentView,
} from './api'
import './attachment.css'

type Props = {
  taskId: string
  /** PM/MEMBER=true，VIEWER=false；这里只控制体验，服务端仍重新鉴权。 */
  canWrite: boolean
}

function sizeLabel(bytes: number): string {
  if (bytes < 1_000) return `${bytes} B`
  if (bytes < 1_000_000) return `${(bytes / 1_000).toFixed(1)} KB`
  return `${(bytes / 1_000_000).toFixed(1)} MB`
}

export default function TaskAttachmentPanel({ taskId, canWrite }: Props) {
  const [items, setItems] = useState<AttachmentView[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const reload = useCallback(async () => {
    try {
      setItems((await listTaskAttachments(taskId)).items)
      setError(null)
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : '附件加载失败')
    }
  }, [taskId])

  useEffect(() => {
    void reload()
  }, [reload])

  async function onSelect(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    event.target.value = ''
    if (!file) return
    const validation = validateAttachmentFile(file)
    if (validation) {
      setError(validation)
      return
    }
    setBusy(true)
    setError(null)
    try {
      await uploadTaskAttachment(taskId, file)
      await reload()
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : '上传失败')
    } finally {
      setBusy(false)
    }
  }

  async function remove(item: AttachmentView) {
    setBusy(true)
    setError(null)
    try {
      await deleteAttachment(item.id)
      await reload()
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : '删除失败')
    } finally {
      setBusy(false)
    }
  }

  async function download(item: AttachmentView) {
    try {
      await downloadAttachment(item)
      setError(null)
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : '下载失败')
    }
  }

  return (
    <section className="task-attachments" aria-label="任务附件">
      <div className="task-attachments-heading">
        <strong>附件（{items === null ? '…' : items.length}）</strong>
        {canWrite ? (
          <>
            <input
              ref={inputRef}
              className="attachment-file-input"
              type="file"
              accept=".png,.jpg,.jpeg,.webp,.pdf,.docx,.xlsx,.zip"
              onChange={(event) => void onSelect(event)}
            />
            <button type="button" disabled={busy} onClick={() => inputRef.current?.click()}>
              {busy ? '处理中…' : '上传附件'}
            </button>
          </>
        ) : null}
      </div>

      <p className="attachment-help">单文件不超过 10MB；支持图片、PDF、DOCX、XLSX、ZIP。</p>
      {error ? <p className="error" role="alert">{error}</p> : null}
      {items === null && !error ? <p className="muted">正在加载…</p> : null}
      {items?.length === 0 ? <p className="muted">暂无附件</p> : null}
      {items && items.length > 0 ? (
        <ul className="attachment-list">
          {items.map((item) => (
            <li key={item.id}>
              <span>
                <strong>{item.originalName}</strong>
                <small>{sizeLabel(item.sizeBytes)}</small>
              </span>
              <span className="attachment-actions">
                <button type="button" className="ghost" onClick={() => void download(item)}>
                  下载
                </button>
                {canWrite ? (
                  <button type="button" className="danger" disabled={busy} onClick={() => void remove(item)}>
                    删除
                  </button>
                ) : null}
              </span>
            </li>
          ))}
        </ul>
      ) : null}
    </section>
  )
}

import { createPrismaAiStorySource } from './modules/ai/story-source.js'
import { createTaskStartGuardPort } from './modules/task/rules.js'
import type { RequirementBreakdownRecord } from './shared/ai.js'
import type {
  DomainEventPublisherPort,
  DomainEventQueryPort,
  DomainEventReplayPort,
  DomainEventSubscriberPort,
} from './shared/events.js'

/**
 * 挂到 Fastify 实例上的事件公共端口（业务域只依赖这些端口，不 import D 的 service）。
 *
 * 组装点唯一（`DECISIONS.md` `arch.shared-ports-and-assembly`）：仓储适配器、权限适配器、
 * D 的事件实现都在这里显式注入；生命周期由 `onReady` / `onClose` 驱动。
 */
export type EventPorts = {
  publisher: DomainEventPublisherPort
  subscriber: DomainEventSubscriberPort
  query: DomainEventQueryPort
  replay: DomainEventReplayPort
}

declare module 'fastify' {
  interface FastifyInstance {
    /** 领域事件公共端口（由 `buildApp` 组装注入）。 */
    events: EventPorts
  }
}

export type BuildAppOptions = {
  /** 是否开启 Fastify 日志。测试环境建议关闭，避免噪声。 */
  logger?: boolean
  /**
   * 数据库客户端注入点。
   *
   * 不传时回落到 `src/db/client.ts` 的全局单例（生产 / 本地开发路径）；
   * 测试传入 `createTempDatabase().prisma` 以使用独立临时库，避免污染 dev.db。
   */
  prisma?: PrismaClient
  /**
   * 附件实体文件存储根（显式注入点）。
   *
   * 生产 / 不传时用项目根 `var/uploads/`（`LocalAttachmentStorage` 默认）；
   * 测试传入 `mkdtemp` 独占临时目录，仅清理自己的目录，**绝不**清理真实 `var/uploads/`。
   */
  uploadRoot?: string
}

export function buildApp(options: BuildAppOptions = {}): FastifyInstance {
  const app = Fastify({
    logger: options.logger ?? process.env.NODE_ENV !== 'test',
  })

  // 不传 prisma 时与原先行为完全一致（回落单例）
  const context: RouteContext = { prisma: options.prisma ?? defaultPrisma }

  // #31 US-11 AI 建议：显式组装模型端口（本轮 `LOCAL_STUB`）、DB 仓储、统一鉴权适配器与只读
  // 故事来源，注入路由总表。业务域通过服务端口复用，不 import D 的 service（契约 I-9）。
  // 外部模式必须显式注入 adapter；配置错误直接阻止启动，禁止静默降级为桩。
  context.aiService = createAiBreakdownService({
    ai: { mode: 'LOCAL_STUB' },
    authorization: createAiAuthorizationPort(context.prisma),
    repository: new PrismaAiSuggestionRepository<RequirementBreakdownRecord>(context.prisma),
    storySource: createPrismaAiStorySource(context.prisma),
  })

  // #36 任务附件（B 公共接入）：显式组装 prisma 仓储 + 本地文件存储 + 统一鉴权适配器，
  // 注入路由总表与生命周期端口。组装点唯一（`DECISIONS.md` `arch.shared-ports-and-assembly`）。
  // 下载不注册静态目录：物理文件只经带鉴权与 Content-Disposition 的下载端点读取。
  // ★ 同一个仓储 / 存储实例同时供 service 与清理生命周期使用（避免两套连接语义）。
  const attachmentRepository = new PrismaAttachmentRepository(context.prisma)
  const attachmentStorage = new LocalAttachmentStorage(options.uploadRoot)
  context.attachmentService = new AttachmentService({
    repository: attachmentRepository,
    storage: attachmentStorage,
    authorization: createAttachmentAuthorizationPort(context.prisma),
  })
