    sizeBytes: content.byteLength,
    storageKey,
    uploaderUserId: seed.memberId,
    uploadedAt: new Date('2026-10-23T00:00:00.000Z').toISOString(),
    state: 'ACTIVE',
    cleanupAttempts: 0,
    cleanupError: null,
  }
  await repository.insert(record)
  return id
}


