import { useEffect, useState } from 'react'
import { Link, NavLink, Outlet, useParams } from 'react-router-dom'
import type { ProjectView } from '../../../src/shared/types'
import { ApiError, getProject } from '../api'
import { ROLE_LABELS } from '../labels'
import EmptyState from '../components/EmptyState'

/**
 * 项目工作台骨架：按 :projectId 拉项目（端点 5），左侧导航 + 子路由内容。
 * 非成员 / 不存在 → 404 页（与后端一致，不泄漏对象）。
 * 子页面用 useOutletContext<ProjectView>() 取项目与 myRole。
 */
type LoadState =
  | { status: 'loading' }
  | { status: 'notfound' }
  | { status: 'error'; message: string }
  | { status: 'ready'; project: ProjectView }

export default function ProjectLayout() {
  const { projectId } = useParams()
  const [state, setState] = useState<LoadState>({ status: 'loading' })
  const [reloadKey, setReloadKey] = useState(0)

  useEffect(() => {
    if (!projectId) {
      setState({ status: 'notfound' })
      return
    }
    let cancelled = false
    setState({ status: 'loading' })
    getProject(projectId)
      .then((project) => {
        if (!cancelled) setState({ status: 'ready', project })
      })
      .catch((err) => {
        if (cancelled) return
        // 只有真正的 404 才当作「不存在 / 无权」；网络或 5xx 不能误报成 404。
        if (err instanceof ApiError && err.status === 404) {
          setState({ status: 'notfound' })
        } else {
          setState({
            status: 'error',
            message: err instanceof ApiError ? err.message : '加载项目失败',
          })
        }
      })
    return () => {
      cancelled = true
    }
  }, [projectId, reloadKey])

  if (state.status === 'loading') {
    return <div className="page-loading">加载中…</div>
  }

  if (state.status === 'notfound') {
    return (
      <div className="project-notfound">
        <EmptyState
          level={1}
          title="项目不存在或无权访问"
          hint="它可能已被删除，或你不在该项目中。"
        />
        <Link className="link" to="/projects">
          返回项目列表
        </Link>
      </div>
    )
  }

  if (state.status === 'error') {
    return (
      <div className="project-notfound">
        <EmptyState level={1} title="项目加载失败" hint={state.message} />
        <div className="page-header-actions">
          <button type="button" onClick={() => setReloadKey((k) => k + 1)}>
            重试
          </button>
          <Link className="link" to="/projects">
            返回项目列表
          </Link>
        </div>
      </div>
    )
  }

  const { project } = state
  const navClass = ({ isActive }: { isActive: boolean }) =>
    isActive ? 'nav-item active' : 'nav-item'

  return (
    <div className="project-layout">
      <aside className="project-sidebar">
        <div className="project-sidebar-head">
          <span className="sidebar-brand">爱管理</span>
          <span className="sidebar-kicker">PROJECT SPACE</span>
          <div className="sidebar-project-name" title={project.name}>{project.name}</div>
        </div>
        <nav className="project-nav" aria-label="项目导航">
          <NavLink to="overview" className={navClass}>
            <span aria-hidden="true">◫</span>概览
          </NavLink>
          {/* US-10 项目仪表盘（工单 #30）：进度 / 健康度。
              属冻结区（前端骨架），由 ROLE-A 按项目负责人 2026-10-18 批复第 3、4 项
              「在 B 的登记范围内自行挂载」落地（登记已发 B）。 */}
          <NavLink to="dashboard" className={navClass}>
            <span aria-hidden="true">◔</span>仪表盘
          </NavLink>
          <NavLink to="requirements" className={navClass}>
            <span aria-hidden="true">◇</span>需求
          </NavLink>
          <NavLink to="tasks" className={navClass}>
            <span aria-hidden="true">☑</span>任务
          </NavLink>
          {/* US-09 任务验收（工单 #29）：验收工作台入口。
              这行属冻结区（前端骨架），已按 #24 comment 6235528115 的申请口径落地；
              **尚无原 owner 的书面授权**，需单人复核合入（口径见 docs/us-09-acceptance-api.md §11）。 */}
          <NavLink to="acceptance" className={navClass}>
            <span aria-hidden="true">✓</span>验收
          </NavLink>
          {/* US-10 风险台账与项目关闭（工单 #30）：
              属冻结区（前端骨架），同上按批复第 3、4 项在登记范围内自行挂载。 */}
          <NavLink to="risks" className={navClass}>
            <span aria-hidden="true">⚠</span>风险
          </NavLink>
          <NavLink to="members" className={navClass}>
            <span aria-hidden="true">♙</span>成员
          </NavLink>
          {/* US-07 成员任务图与负载（工单 #27）：只读负载总览入口。
              行属冻结区（前端骨架），由公共单写人 B 按已授权范围落地（#27 公共挂载批次）。 */}
          <NavLink to="workload" className={navClass}>
            <span aria-hidden="true">◍</span>成员负载
          </NavLink>
          {/* US-06 甘特图（工单 #26）：统一时间轴（需求/任务/里程碑/FS 依赖）入口。
              行属冻结区（前端骨架），由公共单写人 B 按已授权范围落地（#26 公共挂载批次）。 */}
          <NavLink to="gantt" className={navClass}>
            <span aria-hidden="true">▤</span>甘特图
          </NavLink>
          {/* US-04 故事看板（工单 #25）：只读三列看板入口（本批只读；状态写入属 #18）。
              行属冻结区（前端骨架），由公共单写人 B 按已授权范围落地（#25 公共挂载批次）。 */}
          <NavLink to="board" className={navClass}>
            <span aria-hidden="true">▥</span>故事看板
          </NavLink>
          {/* US-15 UML（工单 #35）：用例图 / 时序图入口。行属冻结区（前端骨架），
              由公共单写人 B 按已授权范围落地（#35 P4/P5 挂载批次）。 */}
          <NavLink to="uml" className={navClass}>
            <span aria-hidden="true">◫</span>UML 图
          </NavLink>
        </nav>
        <Link className="project-switcher" to="/projects">
          <span>当前项目 · {ROLE_LABELS[project.myRole]}</span>
          <strong>{project.name}</strong>
        </Link>
      </aside>
      <section className="project-content">
        <Outlet context={project} />
      </section>
    </div>
  )
}

